	//        "tradeFee":"0.00226164",
	//        "tradeAmount":"1.13082",
	//        "filledQuantity":"3",
	//        "filledAmount":"1.13082",
	//        "ts":1685371921945,
	//        "source":"WEB",
	//        "orderAmount":"0",
	//        "matchRole":"TAKER"
	//     }
	//
	var market map[string]any = ccxt.GetArgMap(optionalArgs, 0, nil)
	_ = market
	var marketId *string = this.SafeString(trade, "symbol")
	var marketResolved map[string]any = this.SafeMarket(marketId, market)
	var timestamp *int64 = this.SafeInteger(trade, "createTime")
	var takerMaker *string = this.SafeStringLower2(trade, "matchRole", "taker")
	return ccxt.TradeToMap(this.SafeTrade(map[string]any{
		"info":         trade,
		"id":           this.SafeString2(trade, "id", "tradeId"),
		"symbol":       this.SafeString(marketResolved, "symbol"),
		"timestamp":    timestamp,
		"datetime":     this.Iso8601(timestamp),
		"order":        this.SafeString(trade, "orderId"),
		"type":         this.SafeStringLower(trade, "type"),
		"side":         this.SafeStringLower2(trade, "takerSide", "side"),
		"takerOrMaker": takerMaker,
		"price":        this.OmitZero(this.SafeString2(trade, "tradePrice", "price")),
		"amount":       this.OmitZero(this.SafeString2(trade, "filledQuantity", "quantity")),
		"cost":         this.SafeString2(trade, "amount", "filledAmount"),
		"fee": map[string]any{
			"rate":     nil,
			"cost":     this.SafeString(trade, "tradeFee"),
			"currency": this.SafeString(trade, "feeCurrency"),
		},
	}, marketResolved))
