func (this *Poloniex) HandleOrder(client any, message map[string]any) any {
	//
	// ccxt.Order is created
	//
	//    {
	//        "channel": "orders",
	//        "data": [
	//            {
	//                "symbol": "BTC_USDT",
	//                "type": "LIMIT",
	//                "quantity": "1",
	//                "orderId": "32471407854219264",
	//                "tradeFee": "0",
	//                "clientOrderId": "",
	//                "accountType": "SPOT",
	//                "feeCurrency": "",
	//                "eventType": "place",
	//                "source": "API",
	//                "side": "BUY",
	//                "filledQuantity": "0",
	//                "filledAmount": "0",
	//                "matchRole": "MAKER",
	//                "state": "NEW",
	//                "tradeTime": 0,
	//                "tradeAmount": "0",
	//                "orderAmount": "0",
	//                "createTime": 1648708186922,
	//                "price": "47112.1",
	//                "tradeQty": "0",
	//                "tradePrice": "0",
	//                "tradeId": "0",
	//                "ts": 1648708187469
	//            }
	//        ]
	//    }
	//
	var data []any = ccxt.SafeListTyped(message, "data")
	if this.Orders == nil {
		var limit *int64 = this.SafeInteger(this.Options, "ordersLimit")
		this.Orders = ccxt.NewArrayCacheBySymbolById(limit)
	}
	var orders any = this.Orders
	var marketIds []any = []any{}
	for i := 0; i < len(data); i++ {
		var order map[string]any = ccxt.SafeMapTyped(data, i)
		var marketId *string = this.SafeString(order, "symbol")
		var eventType *string = this.SafeString(order, "eventType")
		if marketId != nil {
			var symbol *string = this.SafeSymbol(marketId)
			var orderId *string = this.SafeString(order, "orderId", "")
			var clientOrderId *string = this.SafeString(order, "clientOrderId", "")
			if (eventType != nil && *eventType == "place") || (eventType != nil && *eventType == "canceled") {
				var parsed map[string]any = this.ParseWsOrder(order)
				orders.(ccxt.Appender).Append(parsed)
			} else {
				var previousOrders map[string]any = ccxt.SafeMapTyped(orders.(*ccxt.ArrayCache).Hashmap, symbol)
				var previousOrder any = this.SafeDict2(previousOrders, orderId, clientOrderId)
				var trade map[string]any = this.ParseWsTrade(order)
				this.HandleMyTrades(client, trade)
				if previousOrder == nil {
					// fill event for an order missing from the cache (e.g. placed before subscribing or after a reconnect) - parse as a fresh order instead of aggregating
					var parsedOrder map[string]any = this.ParseWsOrder(order)
					orders.(ccxt.Appender).Append(parsedOrder)
					marketIds = append(marketIds, marketId)
					continue
				}
				if ccxt.IsEqual(ccxt.GetValue(previousOrder, "trades"), nil) {
					ccxt.AddElementToObject(previousOrder, "trades", []any{})
				}
				retRes104920 := ccxt.GetValue(previousOrder, "trades")
				ccxt.AppendToArray(&retRes104920, trade)
				ccxt.AddElementToObject(previousOrder, "trades", retRes104920)
				ccxt.AddElementToObject(previousOrder, "lastTradeTimestamp", trade["timestamp"])
				var totalCost any = "0"
				var totalAmount any = "0"
				var previousOrderTrades []any = ccxt.SafeListTyped(previousOrder, "trades")
				for j := 0; j < len(previousOrderTrades); j++ {
					var previousOrderTrade map[string]any = ccxt.SafeMapTyped(previousOrderTrades, j)
					var cost *string = this.NumberToString(previousOrderTrade["cost"])
					var amount *string = this.NumberToString(previousOrderTrade["amount"])
					totalCost = ccxt.Precise.StringAdd(totalCost, cost)
					totalAmount = ccxt.Precise.StringAdd(totalAmount, amount)
				}
				if ccxt.Precise.StringGt(totalAmount, "0") {
					ccxt.AddElementToObject(previousOrder, "average", this.ParseNumber(ccxt.Precise.StringDiv(totalCost, totalAmount)))
				}
				ccxt.AddElementToObject(previousOrder, "cost", this.ParseNumber(totalCost))
				if !ccxt.IsEqual(ccxt.GetValue(previousOrder, "filled"), nil) {
					var tradeAmount *string = this.NumberToString(trade["amount"])
					var previousOrderFilled *string = this.NumberToString(ccxt.GetValue(previousOrder, "filled"))
					previousOrderFilled = ccxt.Precise.StringAdd(previousOrderFilled, tradeAmount)
					ccxt.AddElementToObject(previousOrder, "filled", previousOrderFilled)
					if !ccxt.IsEqual(ccxt.GetValue(previousOrder, "amount"), nil) {
						var previousOrderAmount *string = this.NumberToString(ccxt.GetValue(previousOrder, "amount"))
						ccxt.AddElementToObject(previousOrder, "remaining", this.ParseNumber(ccxt.Precise.StringSub(previousOrderAmount, previousOrderFilled)))
					}
				}
				if ccxt.IsEqual(ccxt.GetValue(previousOrder, "fee"), nil) {
					ccxt.AddElementToObject(previousOrder, "fee", map[string]any{
						"rate":     nil,
						"cost":     0,
						"currency": this.SafeString(trade["fee"], "currency"),
					})
				}
				if (!ccxt.IsEqual(ccxt.GetValue(ccxt.GetValue(previousOrder, "fee"), "cost"), nil)) && (this.SafeNumber(trade["fee"], "cost") != nil) {
					var stringOrderCost *string = this.NumberToString(ccxt.GetValue(ccxt.GetValue(previousOrder, "fee"), "cost"))
					var stringTradeCost *string = this.NumberToString(this.SafeNumber(trade["fee"], "cost"))
					ccxt.AddElementToObject(ccxt.GetValue(previousOrder, "fee"), "cost", ccxt.Precise.StringAdd(stringOrderCost, stringTradeCost))
				}
				var rawState *string = this.SafeString(order, "state")
				var state *string = this.ParseStatus(rawState)
				ccxt.AddElementToObject(previousOrder, "status", state)
				// update the newUpdates count
				orders.(ccxt.Appender).Append(previousOrder)
			}
			marketIds = append(marketIds, marketId)
		}
	}
	for i := 0; i < len(marketIds); i++ {
		var marketId *string = ccxt.SafeStringPtr(ccxt.DerefScalar(marketIds[i]))
		var market map[string]any = this.Market(marketId)
		var symbol *string = this.SafeString(market, "symbol", "")
		var messageHash string = "orders::" + *symbol
		client.(ccxt.ClientInterface).Resolve(orders, messageHash)
	}
	client.(ccxt.ClientInterface).Resolve(orders, "orders")
	return message
}
func (this *Poloniex) ParseWsOrder(order any, optionalArgs ...any) map[string]any {
	//
	//    {
	//        "symbol": "BTC_USDT",
	//        "type": "LIMIT",
	//        "quantity": "1",
	//        "orderId": "32471407854219264",
	//        "tradeFee": "0",
	//        "clientOrderId": "",
	//        "accountType": "SPOT",
	//        "feeCurrency": "",
	//        "eventType": "place",
	//        "source": "API",
	//        "side": "BUY",
	//        "filledQuantity": "0",
	//        "filledAmount": "0",
	//        "matchRole": "MAKER",
	//        "state": "NEW",
	//        "tradeTime": 0,
	//        "tradeAmount": "0",
	//        "orderAmount": "0",
	//        "createTime": 1648708186922,
	//        "price": "47112.1",
	//        "tradeQty": "0",
	//        "tradePrice": "0",
	//        "tradeId": "0",
	//        "ts": 1648708187469
	//    }
	//
	var market map[string]any = ccxt.GetArgMap(optionalArgs, 0, nil)
	_ = market
	var id *string = this.SafeString(order, "orderId")
	var clientOrderId *string = this.SafeString(order, "clientOrderId")
	var marketId *string = this.SafeString(order, "symbol")
	var timestamp *string = this.SafeString(order, "ts")
	var filledAmount *string = this.SafeString(order, "filledAmount")
	var status *string = this.SafeString(order, "state")
	var trades any = nil
	if !ccxt.Precise.StringEq(filledAmount, "0") {
		trades = []any{}
		var trade any = this.ParseWsOrderTrade(order)
		ccxt.AppendToArray(&trades, trade)
	}
	return ccxt.OrderToMap(this.SafeOrder(map[string]any{
		"info":               order,
		"symbol":             this.SafeSymbol(marketId, market),
		"id":                 id,
		"clientOrderId":      clientOrderId,
		"timestamp":          timestamp,
		"datetime":           this.Iso8601(timestamp),
		"lastTradeTimestamp": nil,
		"type":               this.SafeString(order, "type"),
		"timeInForce":        nil,
		"postOnly":           nil,
		"side":               this.SafeString(order, "side"),
		"price":              this.SafeString(order, "price"),
		"stopPrice":          nil,
		"triggerPrice":       nil,
		"amount":             this.SafeString(order, "quantity"),
		"cost":               nil,
		"average":            nil,
		"filled":             filledAmount,
		"remaining":          this.SafeString(order, "remaining_size"),
		"status":             this.ParseStatus(status),
		"fee": map[string]any{
			"rate":     nil,
			"cost":     this.SafeString(order, "tradeFee"),
			"currency": this.SafeString(order, "feeCurrency"),
		},
		"trades": trades,
	}))
}
func (this *Poloniex) HandleTicker(client any, message map[string]any) any {
	//
	//    {
	//        "channel": "ticker",
	//        "data": [
	//            {
	//                "symbol": "BTC_USDT",
	//                "startTime": 1677280800000,
	//                "open": "23154.32",
	//                "high": "23212.21",
	//                "low": "22761.01",
	//                "close": "23148.86",
	//                "quantity": "105.179566",
	//                "amount": "2423161.17436702",
	//                "tradeCount": 17582,
	//                "dailyChange": "-0.0002",
	//                "markPrice": "23151.09",
	//                "closeTime": 1677367197924,
	//                "ts": 1677367251090
	//            }
	//        ]
	//    }
	//
	var data []any = ccxt.SafeListTyped(message, "data")
	var newTickers map[string]any = map[string]any{}
	for i := 0; i < len(data); i++ {
		var item any = ccxt.DerefScalar(data[i])
		var marketId *string = this.SafeString(item, "symbol")
		if marketId != nil {
			var ticker map[string]any = ccxt.TickerToMap(this.ParseTicker(item))
			var symbol *string = this.SafeString(ticker, "symbol")
			if symbol != nil {
				this.Tickers.Store(symbol, ticker)
			}
			if symbol != nil {
				newTickers[*symbol] = ticker
			}
		}
	}
	var messageHashes []any = ccxt.ArrayTyped(this.FindMessageHashes(ccxt.AsClient(client), "ticker::"))
	for i := 0; i < len(messageHashes); i++ {
		var messageHash *string = ccxt.SafeStringPtr(messageHashes[i])
		var parts []string = strings.Split(*messageHash, "::")
		var symbolsString *string = ccxt.SafeStringPtr(func() any {
			if 1 >= 0 && 1 < len(parts) {
				return parts[1]
			}
			return nil
		}())
		var symbols []string = strings.Split(*symbolsString, ",")
		var tickers any = this.FilterByArray(newTickers, "symbol", symbols)
		if !this.IsEmpty(tickers) {
			client.(ccxt.ClientInterface).Resolve(tickers, messageHash)
		}
	}
	client.(ccxt.ClientInterface).Resolve(newTickers, "ticker")
	return message
}
func (this *Poloniex) HandleOrderBook(client any, message map[string]any) {
	//
	// snapshot
	//
	//    {
	//        "channel": "book_lv2",
	//        "data": [
	//            {
	//                "symbol": "BTC_USDT",
	//                "createTime": 1677368876253,
	//                "asks": [
	//                    ["5.65", "0.02"],
	//                    ...
	//                ],
	//                "bids": [
	//                    ["6.16", "0.6"],
	//                    ...
	//                ],
	//                "lastId": 164148724,
	//                "id": 164148725,
	//                "ts": 1677368876316
	//            }
	//        ],
	//        "action": "snapshot"
	//    }
	//
	// update
	//
	//    {
	//        "channel": "book_lv2",
	//        "data": [
	//            {
	//                "symbol": "BTC_USDT",
	//                "createTime": 1677368876882,
	//                "asks": [
	//                    ["6.35", "3"]
	//                ],
	//                "bids": [
	//                    ["5.65", "0.02"]
	//                ],
	//                "lastId": 164148725,
	//                "id": 164148726,
	//                "ts": 1677368876890
	//            }
	//        ],
	//        "action": "update"
	//    }
	//
	var data []any = ccxt.SafeListTyped(message, "data")
	var typeVar *string = this.SafeString(message, "action")
	var snapshot bool = (typeVar != nil && *typeVar == "snapshot")
	var update bool = (typeVar != nil && *typeVar == "update")
	for i := 0; i < len(data); i++ {
		var item map[string]any = ccxt.SafeMapTyped(data, i)
		var marketId *string = this.SafeString(item, "symbol")
		var market map[string]any = this.SafeMarket(marketId)
		var symbol *string = ccxt.SafeStringPtr(market["symbol"])
		var name string = "book_lv2"
		var messageHash string = name + "::" + *symbol
		var subscription map[string]any = client.(ccxt.ClientInterface).SubscriptionDict(messageHash)
		var limit *int64 = this.SafeInteger(subscription, "limit")
		var timestamp *int64 = this.SafeInteger(item, "ts")
		var asks []any = ccxt.SafeListTyped(item, "asks")
		var bids []any = ccxt.SafeListTyped(item, "bids")
		if snapshot || update {
			var orderbook ccxt.OrderBookInterface = ccxt.OrderBookTyped(this.SafeValue(this.Orderbooks, symbol))
			if snapshot && (ccxt.IsEqual(orderbook, nil)) {
				orderbook = this.OrderBook(map[string]any{}, limit)
				this.Orderbooks[*symbol] = orderbook
			}
			if ccxt.IsEqual(orderbook, nil) {
				continue
			}
			if snapshot {
				// reset the existing orderbook in place instead of
				// replacing it: a consumer awakened earlier keeps a
				// reference to the old object and would be orphaned
				// from later updates on a resync/reconnect otherwise
				orderbook.(ccxt.OrderBookInterface).Reset(map[string]any{})
			}
			if bids != nil {
				for j := 0; j < len(bids); j++ {
					var bid []any = ccxt.SafeListTyped(bids, j)
					var price *float64 = this.SafeNumber(bid, 0)
					var amount *float64 = this.SafeNumber(bid, 1)
					var bidsSide any = orderbook.GetBids()
					bidsSide.(ccxt.IOrderBookSide).Store(price, amount)
				}
			}
			if asks != nil {
				for j := 0; j < len(asks); j++ {
					var ask []any = ccxt.SafeListTyped(asks, j)
					var price *float64 = this.SafeNumber(ask, 0)
					var amount *float64 = this.SafeNumber(ask, 1)
					var asksSide any = orderbook.GetAsks()
					asksSide.(ccxt.IOrderBookSide).Store(price, amount)
				}
			}
			ccxt.AddElementToObject(orderbook, "symbol", symbol)
			ccxt.AddElementToObject(orderbook, "timestamp", timestamp)
			ccxt.AddElementToObject(orderbook, "datetime", this.Iso8601(timestamp))
			client.(ccxt.ClientInterface).Resolve(orderbook, messageHash)
		}
	}
}
func (this *Poloniex) HandleBalance(client any, message map[string]any) {
	//
	//    {
	//       "channel": "balances",
	//       "data": [
	//            {
	//                "changeTime": 1657312008411,
	//                "accountId": "1234",
	//                "accountType": "SPOT",
	//                "eventType": "place_order",
	//                "available": "9999999983.668",
	//                "currency": "BTC",
	//                "id": 60018450912695040,
	//                "userId": 12345,
	//                "hold": "16.332",
	//                "ts": 1657312008443
	//            }
	//        ]
	//    }
	//
	// the balances channel only sends per-event deltas for the currencies
	// that changed, so merge them into the existing balance object instead
	// of rebuilding it from the current message: a rebuilt object would
	// drop every other currency, and a consumer awakened by an earlier
	// message keeps a reference to the old object while ccxt.Client.resolve is
	// a no-op with no waiter, so updates landing in that window would
	// never reach that consumer (same class as kraken issue #26773)
	var data []any = ccxt.SafeListTyped(message, "data")
	var messageHash string = "balances"
	if this.Balance == nil {
		this.Balance = map[string]any{}
	}
	this.Balance["info"] = this.SafeList(message, "data", []any{})
	var firstBalance map[string]any = ccxt.SafeMapTyped(data, 0)
	var timestamp *int64 = this.SafeInteger(firstBalance, "ts")
	ccxt.AddElementToObject(this.Balance, "timestamp", timestamp)
	this.Balance["datetime"] = this.Iso8601(timestamp)
	for i := 0; i < len(data); i++ {
		var balance map[string]any = ccxt.SafeMapTyped(data, i)
		var currencyId *string = this.SafeString(balance, "currency")
		var code *string = this.SafeCurrencyCode(currencyId)
		var newAccount map[string]any = this.Account()
		newAccount["free"] = this.SafeString(balance, "available")
		newAccount["used"] = this.SafeString(balance, "hold")
		if code != nil {
			this.Balance[*code] = newAccount
		}
	}
	this.WsBalanceReplace(this.SafeBalance(this.Balance))
	client.(ccxt.ClientInterface).Resolve(this.Balance, messageHash)
}
func (this *Poloniex) HandleMyTrades(client any, parsedTrade map[string]any) {
	// emulated using the orders' stream
	var messageHash string = "myTrades"
	var symbol *string = this.SafeString(parsedTrade, "symbol", "")
	if this.MyTrades == nil {
		var limit *int64 = this.SafeInteger(this.Options, "tradesLimit", 1000)
		this.MyTrades = ccxt.NewArrayCacheBySymbolById(limit)
	}
	var trades any = this.MyTrades
	trades.(ccxt.Appender).Append(parsedTrade)
	client.(ccxt.ClientInterface).Resolve(trades, messageHash)
	var symbolMessageHash string = messageHash + ":" + *symbol
	client.(ccxt.ClientInterface).Resolve(trades, symbolMessageHash)
}
func (this *Poloniex) HandlePong(client any) {
	client.(ccxt.ClientInterface).SetLastPong(this.Milliseconds())
}
func (this *Poloniex) HandleMessage(client any, message map[string]any) {
	if this.HandleErrorMessage(client, message) == true {
		return
	}
	var typeVar *string = this.SafeString(message, "channel")
	var event *string = this.SafeString(message, "event")
	if event != nil && *event == "pong" {
		client.(ccxt.ClientInterface).SetLastPong(this.Milliseconds())
	}
	if event != nil && *event == "unsubscribe" {
		this.HandleUnsubscription(client, message)
		return
	}
	var methods map[string]any = map[string]any{
		"candles_minute_1":  this.HandleOHLCV,
		"candles_minute_5":  this.HandleOHLCV,
		"candles_minute_10": this.HandleOHLCV,
		"candles_minute_15": this.HandleOHLCV,
		"candles_minute_30": this.HandleOHLCV,
		"candles_hour_1":    this.HandleOHLCV,
		"candles_hour_2":    this.HandleOHLCV,
		"candles_hour_4":    this.HandleOHLCV,
		"candles_hour_6":    this.HandleOHLCV,
		"candles_hour_12":   this.HandleOHLCV,
		"candles_day_1":     this.HandleOHLCV,
		"candles_day_3":     this.HandleOHLCV,
		"candles_week_1":    this.HandleOHLCV,
		"candles_month_1":   this.HandleOHLCV,
		"book":              this.HandleOrderBook,
		"book_lv2":          this.HandleOrderBook,
		"ticker":            this.HandleTicker,
		"trades":            this.HandleTrade,
		"orders":            this.HandleOrder,
		"balances":          this.HandleBalance,
		"createOrder":       this.HandleOrderRequest,
		"cancelOrder":       this.HandleOrderRequest,
		"cancelAllOrders":   this.HandleOrderRequest,
		"auth":              this.HandleAuthenticate,
	}
	var method any = func() any {
		if typeVar == nil {
			return nil
		}
		return this.SafeValue(methods, typeVar)
	}()
	if typeVar != nil && *typeVar == "auth" {
		this.HandleAuthenticate(client, message)
	} else if typeVar == nil {
		this.HandleOrderRequest(client, message)
	} else {
		var data []any = ccxt.SafeListTyped(message, "data")
		var dataLength int = len(data)
		if dataLength > 0 {
			ccxt.CallDynamically(method, client, message)
		}
	}
}
func (this *Poloniex) HandleUnsubscription(client any, message map[string]any) {
	//
	//    {
	//        "event": "unsubscribe",
	//        "channel": "trades",
	//        "symbols": [ "ETH_USDT", "BTC_USDT" ]
	//    }
	//
	var channel *string = this.SafeString(message, "channel", "")
	var marketIds []any = ccxt.SafeListTyped(message, "symbols")
	var timeframes map[string]any = this.SafeDictMap(this.Options, "timeframes", map[string]any{})
	var timeframe *string = this.FindTimeframe(channel, timeframes)
	for i := 0; i < len(marketIds); i++ {
		var symbol *string = this.SafeSymbol(this.SafeString(marketIds, i))
		var subMessageHash string = *channel + "::" + *symbol
		if channel != nil && *channel == "trades" {
			this.CleanCache(map[string]any{
				"topic":   "trades",
				"symbols": []any{symbol},
			})
			this.CleanUnsubscription(ccxt.AsClient(client), subMessageHash, "unsubscribe:"+subMessageHash)
		} else if timeframe != nil {
			this.CleanCache(map[string]any{
				"topic":                "ohlcv",
				"symbolsAndTimeframes": []any{[]any{symbol, timeframe}},
			})
			this.CleanUnsubscription(ccxt.AsClient(client), subMessageHash, "unsubscribe:"+subMessageHash)
		}
	}
}
func (this *Poloniex) HandleErrorMessage(client any, message map[string]any) any {
	//
	//    {
	//        message: 'Invalid channel value ["ordersss"]',
	//        event: 'error'
	//    }
	//
	//    {
	//        "orderId": 0,
	//        "clientOrderId": null,
	//        "message": "Currency trade disabled",
	//        "code": 21352
	//    }
	//
	//    {
	//       "event": "error",
	//       "message": "Platform in maintenance mode"
	//    }
	//    {
	//       "id":"1722386782048",
	//       "data":[
	//          {
	//             "orderId":0,
	//             "clientOrderId":null,
	//             "message":"available insufficient",
	//             "code":21721
	//          }
	//       ]
	//    }
	//
	var id *string = this.SafeString(message, "id")
	var event *string = this.SafeString(message, "event")
	var data []any = ccxt.SafeListTyped(message, "data")
	var first map[string]any = ccxt.SafeMapTyped(data, 0)
	var orderId *string = this.SafeString(first, "orderId")
	if (event != nil && *event == "error") || (orderId != nil && *orderId == "0") {

		{
			ret__ := func(this *Poloniex) (ret_ any) {
				defer func() {
					if e := recover(); e != nil {
						if e == "break" {
							return
						}
						ret_ = func(this *Poloniex) any {
							// catch block:
							if ccxt.IsInstance(e, ccxt.AuthenticationError) {
								var messageHash string = "authenticated"
								client.(ccxt.ClientInterface).Reject(e, messageHash)
								if client.(ccxt.ClientInterface).SubscriptionHas(messageHash) {
									client.(ccxt.ClientInterface).SubscriptionDel(messageHash)
								}
							} else {
								client.(ccxt.ClientInterface).Reject(e, id)
							}
							return true

						}(this)
					}
				}()
				// try block:
				var error *string = this.SafeString(first, "message")
				var code *string = this.SafeString(first, "code")
				var feedback string = this.Id + " " + this.Json(message)
				this.ThrowExactlyMatchedException(this.Exceptions["exact"], code, feedback)
				this.ThrowBroadlyMatchedException(this.Exceptions["broad"], error, feedback)
				panic(ccxt.ExchangeError(feedback))

			}(this)
			if ret__ != nil {
				return ret__
			}
			return nil
		}
	}
	return false
}
func (this *Poloniex) HandleAuthenticate(client any, message map[string]any) any {
	//
	//    {
	//        "success": true,
	//        "ret_msg": '',
	//        "op": "auth",
	//        "conn_id": "ce3dpomvha7dha97tvp0-2xh"
	//    }
	//
	var data map[string]any = ccxt.SafeMapTyped(message, "data")
	var success *bool = this.SafeBool(data, "success")
	var messageHash string = "authenticated"
	if success != nil && *success == true {
		client.(ccxt.ClientInterface).Resolve(message, messageHash)
	} else {
		error := ccxt.AuthenticationError(this.Id + " " + this.Json(message))
		client.(ccxt.ClientInterface).Reject(error, messageHash)
		if client.(ccxt.ClientInterface).SubscriptionHas(messageHash) {
			client.(ccxt.ClientInterface).SubscriptionDel(messageHash)
		}
	}
	return message
}
